-- monitors.lua - Dynamically loads monitors.conf generated by nwg-displays
---@module 'hl'

local home = os.getenv("HOME") or ""
local config = os.getenv("XDG_CONFIG_HOME") or (home .. "/.config")
local host_file = io.open("/etc/hostname", "r")
local host = host_file and (host_file:read("*l") or "") or ""
if host_file then host_file:close() end
local conf_path = config .. "/hypr/monitors.conf"
local probe = io.open(conf_path, "r")
if probe then probe:close() else conf_path = config .. "/voluta/displays/" .. host .. "/monitors.conf" end

local f = io.open(conf_path, "r")
if f then
    local count = 0
    for raw_line in f:lines() do
        local l = raw_line:gsub("#.*", ""):match("^%s*(.-)%s*$")
        if l and l:match("^monitor%s*=") then
            local val = l:match("^monitor%s*=%s*(.*)$")
            if val and #val > 0 then
                local parts = {}
                for part in val:gmatch("([^,]+)") do
                    table.insert(parts, part:match("^%s*(.-)%s*$"))
                end
                if #parts >= 1 then
                    local output = parts[1]
                    if parts[2] == "disable" then
                        hl.monitor({ output = output, disabled = true })
                    elseif #parts >= 4 then
                        hl.monitor({
                            output = output,
                            mode = parts[2],
                            position = parts[3],
                            scale = tonumber(parts[4]) or parts[4],
                        })
                    elseif #parts == 3 then
                        hl.monitor({
                            output = output,
                            mode = parts[2],
                            position = parts[3],
                        })
                    else
                        hl.monitor({
                            output = output,
                            mode = parts[2] or "preferred",
                            position = parts[3] or "auto",
                            scale = tonumber(parts[4]) or 1.0,
                        })
                    end
                    count = count + 1
                end
            end
        end
    end
    f:close()
    if count > 0 then return end
end

-- Fallback if monitors.conf is empty
hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = 1.0,
})
